INSERT INTO gs_moneda(codigo,nombre,decimales) VALUES ('PYG','Guarani',0) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO gs_empresa(codigo,razon_social,documento_fiscal,pais_codigo,moneda_base_id) SELECT 'DEMO','Empresa demostracion','80000000-0','PY',id FROM gs_moneda WHERE codigo='PYG' AND NOT EXISTS (SELECT 1 FROM gs_empresa WHERE codigo='DEMO');
INSERT INTO gs_sucursal(empresa_id,codigo,nombre) SELECT id,'CASA-CENTRAL','Casa central' FROM gs_empresa WHERE codigo='DEMO' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gs_usuario(login,password_hash,nombre) SELECT 'demo',crypt('demo123',gen_salt('bf')),'Usuario demostracion' WHERE NOT EXISTS (SELECT 1 FROM gs_usuario WHERE lower(login)='demo');
INSERT INTO gs_usuario_empresa(empresa_id,usuario_id) SELECT e.id,u.id FROM gs_empresa e,gs_usuario u WHERE e.codigo='DEMO' AND u.login='demo' ON CONFLICT (empresa_id,usuario_id) DO NOTHING;
INSERT INTO gs_usuario_sucursal(empresa_id,usuario_id,sucursal_id,puede_emitir,supervisor) SELECT e.id,u.id,s.id,TRUE,TRUE FROM gs_empresa e JOIN gs_usuario u ON u.login='demo' JOIN gs_sucursal s ON s.empresa_id=e.id AND s.codigo='CASA-CENTRAL' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,usuario_id,sucursal_id) DO UPDATE SET puede_emitir=TRUE,supervisor=TRUE;
INSERT INTO gp_terminal(empresa_id,sucursal_id,codigo) SELECT e.id,s.id,'POS-01' FROM gs_empresa e JOIN gs_sucursal s ON s.empresa_id=e.id AND s.codigo='CASA-CENTRAL' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gv_lista_precio(empresa_id,codigo,nombre,moneda_id,incluye_impuestos) SELECT e.id,'CONTADO','Lista contado',m.id,FALSE FROM gs_empresa e,gs_moneda m WHERE e.codigo='DEMO' AND m.codigo='PYG' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gs_clase_documento(codigo,modulo,descripcion) VALUES ('VENTA','gv','Venta contado') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO gs_modalidad_emision(codigo,nombre,fiscal,integracion) VALUES ('INTERNA','Emision interna',FALSE,'INTERNA') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO gs_tipo_comprobante(empresa_id,codigo,clase_id,efecto_stock_predeterminado,efecto_financiero,permite_excepcion) SELECT e.id,'VENTA',c.id,'SALIDA',1,TRUE FROM gs_empresa e,gs_clase_documento c WHERE e.codigo='DEMO' AND c.codigo='VENTA' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gs_talonario(empresa_id,sucursal_id,clase_id,modalidad_id,codigo,desde,inicial,final,siguiente,publico_sucursal) SELECT e.id,s.id,c.id,m.id,'VENTA-INT',current_date,1,999999,1,TRUE FROM gs_empresa e JOIN gs_sucursal s ON s.empresa_id=e.id AND s.codigo='CASA-CENTRAL',gs_clase_documento c,gs_modalidad_emision m WHERE e.codigo='DEMO' AND c.codigo='VENTA' AND m.codigo='INTERNA' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gs_talonario_usuario(empresa_id,talonario_id,usuario_id) SELECT e.id,t.id,u.id FROM gs_empresa e JOIN gs_talonario t ON t.empresa_id=e.id AND t.codigo='VENTA-INT' JOIN gs_usuario u ON u.login='demo' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,talonario_id,usuario_id) DO NOTHING;
INSERT INTO gs_clase_documento(codigo,modulo,descripcion) VALUES ('RECIBO','gf','Recibo de cobro') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO gs_talonario(empresa_id,sucursal_id,clase_id,modalidad_id,codigo,desde,inicial,final,siguiente,publico_sucursal) SELECT e.id,s.id,c.id,m.id,'RECIBO-INT',current_date,1,999999,1,TRUE FROM gs_empresa e JOIN gs_sucursal s ON s.empresa_id=e.id AND s.codigo='CASA-CENTRAL',gs_clase_documento c,gs_modalidad_emision m WHERE e.codigo='DEMO' AND c.codigo='RECIBO' AND m.codigo='INTERNA' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gs_talonario_usuario(empresa_id,talonario_id,usuario_id) SELECT e.id,t.id,u.id FROM gs_empresa e JOIN gs_talonario t ON t.empresa_id=e.id AND t.codigo='RECIBO-INT' JOIN gs_usuario u ON u.login='demo' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,talonario_id,usuario_id) DO NOTHING;
INSERT INTO gp_permiso_offline(empresa_id,terminal_id,usuario_id,emitido_en,vence_en,supervisor,firma) SELECT e.id,t.id,u.id,now(),now()+interval '72 hours',TRUE,'DEMO' FROM gs_empresa e JOIN gp_terminal t ON t.empresa_id=e.id AND t.codigo='POS-01' JOIN gs_usuario u ON u.login='demo' WHERE e.codigo='DEMO' AND NOT EXISTS (SELECT 1 FROM gp_permiso_offline p WHERE p.empresa_id=e.id AND p.terminal_id=t.id AND p.usuario_id=u.id AND p.vence_en>now());
INSERT INTO gs_entidad(empresa_id,codigo,naturaleza,nombre) SELECT id,'CONSUMIDOR-FINAL','PERSONA','Consumidor final' FROM gs_empresa WHERE codigo='DEMO' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gv_cliente(empresa_id,entidad_id,moneda_id) SELECT e.id,n.id,m.id FROM gs_empresa e JOIN gs_entidad n ON n.empresa_id=e.id AND n.codigo='CONSUMIDOR-FINAL' JOIN gs_moneda m ON m.codigo='PYG' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,entidad_id) DO NOTHING;
INSERT INTO gi_unidad_medida(codigo,nombre,dimension) VALUES ('UN','Unidad','UNIDAD') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO gi_producto(empresa_id,codigo,nombre,tipo) SELECT id,'ARROZ-1KG','Arroz 1 kg','MERCADERIA' FROM gs_empresa WHERE codigo='DEMO' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gi_articulo(empresa_id,producto_id,codigo,descripcion,unidad_base_id) SELECT e.id,p.id,'ARROZ-1KG','Arroz 1 kg',u.id FROM gs_empresa e JOIN gi_producto p ON p.empresa_id=e.id AND p.codigo='ARROZ-1KG' JOIN gi_unidad_medida u ON u.codigo='UN' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gi_presentacion(empresa_id,articulo_id,codigo,unidad_id,factor_base) SELECT e.id,a.id,'UN',u.id,1 FROM gs_empresa e JOIN gi_articulo a ON a.empresa_id=e.id AND a.codigo='ARROZ-1KG' JOIN gi_unidad_medida u ON u.codigo='UN' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,articulo_id,codigo) DO NOTHING;
INSERT INTO gi_codigo_barra(empresa_id,presentacion_id,codigo) SELECT e.id,p.id,'779001' FROM gs_empresa e JOIN gi_articulo a ON a.empresa_id=e.id AND a.codigo='ARROZ-1KG' JOIN gi_presentacion p ON p.empresa_id=e.id AND p.articulo_id=a.id AND p.codigo='UN' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gi_deposito(empresa_id,sucursal_id,codigo,nombre) SELECT e.id,s.id,'PRINCIPAL','Deposito principal' FROM gs_empresa e JOIN gs_sucursal s ON s.empresa_id=e.id AND s.codigo='CASA-CENTRAL' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gi_ubicacion(empresa_id,deposito_id,codigo) SELECT e.id,d.id,'GENERAL' FROM gs_empresa e JOIN gi_deposito d ON d.empresa_id=e.id AND d.codigo='PRINCIPAL' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,deposito_id,codigo) DO NOTHING;
INSERT INTO gi_posicion(empresa_id,ubicacion_id,articulo_id) SELECT e.id,u.id,a.id FROM gs_empresa e JOIN gi_ubicacion u ON u.empresa_id=e.id AND u.codigo='GENERAL' JOIN gi_articulo a ON a.empresa_id=e.id AND a.codigo='ARROZ-1KG' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,ubicacion_id,articulo_id,lote_id,serie_id) DO NOTHING;
INSERT INTO gi_existencia(empresa_id,posicion_id,cantidad) SELECT e.id,p.id,100 FROM gs_empresa e JOIN gi_posicion p ON p.empresa_id=e.id JOIN gi_articulo a ON a.empresa_id=e.id AND a.id=p.articulo_id AND a.codigo='ARROZ-1KG' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,posicion_id) DO UPDATE SET cantidad=GREATEST(gi_existencia.cantidad,100);
INSERT INTO gi_valoracion(empresa_id,articulo_id,cantidad,valor,ultimo_costo) SELECT e.id,a.id,100,500000,5000 FROM gs_empresa e JOIN gi_articulo a ON a.empresa_id=e.id AND a.codigo='ARROZ-1KG' WHERE e.codigo='DEMO' ON CONFLICT (empresa_id,articulo_id) DO UPDATE SET cantidad=GREATEST(gi_valoracion.cantidad,100),valor=GREATEST(gi_valoracion.valor,500000),ultimo_costo=5000;
INSERT INTO gv_precio(empresa_id,lista_id,presentacion_id,desde,precio,minimo) SELECT e.id,l.id,p.id,now(),6500,1 FROM gs_empresa e JOIN gv_lista_precio l ON l.empresa_id=e.id AND l.codigo='CONTADO' JOIN gi_articulo a ON a.empresa_id=e.id AND a.codigo='ARROZ-1KG' JOIN gi_presentacion p ON p.empresa_id=e.id AND p.articulo_id=a.id AND p.codigo='UN' WHERE e.codigo='DEMO' AND NOT EXISTS (SELECT 1 FROM gv_precio x WHERE x.empresa_id=e.id AND x.lista_id=l.id AND x.presentacion_id=p.id);
INSERT INTO gf_caja(empresa_id,sucursal_id,codigo,moneda_id) SELECT e.id,s.id,'CAJA-01',m.id FROM gs_empresa e JOIN gs_sucursal s ON s.empresa_id=e.id AND s.codigo='CASA-CENTRAL',gs_moneda m WHERE e.codigo='DEMO' AND m.codigo='PYG' ON CONFLICT (empresa_id,codigo) DO NOTHING;
INSERT INTO gf_medio_pago(empresa_id,codigo,nombre,efectivo) SELECT id,'CASH','Efectivo',TRUE FROM gs_empresa WHERE codigo='DEMO' ON CONFLICT (empresa_id,codigo) DO NOTHING;
