BEGIN;
SET LOCAL search_path = erp_v4, pg_catalog;
SELECT erp_v4.gs_reservar_rango(e.id,t.id,pt.id,u.id,100,'00000000-0000-0000-0000-000000000901'::uuid,FALSE) FROM gs_empresa e JOIN gs_talonario t ON t.empresa_id=e.id AND t.codigo='VENTA-INT' JOIN gp_terminal pt ON pt.empresa_id=e.id AND pt.codigo='POS-01' JOIN gs_usuario u ON u.login='demo' WHERE e.codigo='DEMO' AND NOT EXISTS (SELECT 1 FROM gs_talonario_rango_terminal r WHERE r.uid='00000000-0000-0000-0000-000000000901'::uuid);
SELECT erp_v4.gs_reservar_rango(e.id,t.id,pt.id,u.id,100,'00000000-0000-0000-0000-000000000902'::uuid,FALSE) FROM gs_empresa e JOIN gs_talonario t ON t.empresa_id=e.id AND t.codigo='RECIBO-INT' JOIN gp_terminal pt ON pt.empresa_id=e.id AND pt.codigo='POS-01' JOIN gs_usuario u ON u.login='demo' WHERE e.codigo='DEMO' AND NOT EXISTS (SELECT 1 FROM gs_talonario_rango_terminal r WHERE r.uid='00000000-0000-0000-0000-000000000902'::uuid);
COMMIT;
